def walk_strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, list):
        for item in value:
            for text in walk_strings(item):
                yield text
    elif isinstance(value, dict):
        for item in value.values():
            for text in walk_strings(item):
                yield text


def unicase(value):
    value = unicodedata.normalize("NFD", value or "")
    value = "".join(
        char for char in value if unicodedata.category(char) != "Mn")
    return re.sub(r"\s+", " ", value.casefold()).strip()


def validate_url(value, label):
    parsed = urlparse(value)
    if parsed.scheme != "https" or not parsed.netloc:
        raise ValueError("%s is not a current HTTPS URL: %s" %
                         (label, value))


def clean(source):
    row = {
        key: value for key, value in source.items()
        if value not in (None, "", [])
    }
    row.setdefault("checked", CHECKED)
    sources = list(row.get("sources") or [])
    if not sources:
        raise ValueError("%s lacks an official source" % row.get("id"))
    for source_url in sources:
        validate_url(source_url, row.get("id"))
        if urlparse(source_url).netloc not in {
                "www.iaath.gr", "iaath.gr", "site.mountathos.org"}:
            raise ValueError(
                "%s carries a non-competent identity source" %
                row.get("id"))
    row["sources"] = sources
    row["cite"] = list(sources)
    contact_sources = list(row.get("contact_sources") or [])
    if contact_sources:
        for source_url in contact_sources:
            validate_url(source_url, row.get("id"))
            if source_url not in sources:
                raise ValueError(
                    "%s has contact provenance outside its sources" %
                    row.get("id"))
        row["contact_sources"] = contact_sources
        if row.get("contact_checked") != CHECKED:
            raise ValueError(
                "%s lacks the current contact check date" % row.get("id"))
    if row.get("site"):
        validate_url(row["site"], row.get("id"))
    return row


def validate_ledger():
    ledger = json.loads(CANDIDATE_LEDGER.read_text(encoding="utf-8"))
    if ledger.get("v") != 1 or ledger.get("countries") != ["GR"]:
        raise ValueError("Greece candidate ledger metadata drifted")
    summary = ledger.get("published_summary") or {}
    expected_summary = {
        "archiepiscopal_regions": 21,
        "parishes": 146,
        "cemetery_churches": 12,
        "monasteries_and_hesychasteria": 9,
        "athos_ruling_monasteries": 20,
        "chapels": 155,
        "total": EXPECTED_COUNT,
        "contact_bodies": EXPECTED_CONTACT_BODIES,
    }
    for key, value in expected_summary.items():
        if summary.get(key) != value:
            raise ValueError("Greece candidate ledger %s drifted" % key)
    candidate_ids = {
        item.get("candidate_id") for item in ledger.get("candidates") or []
    }
    expected_ids = {
        "gr-athens-three-unidentified-chapels",
        "gr-athens-monastic-dependencies",
        "gr-church-of-greece-local-rosters",
        "gr-new-lands-local-rosters",
        "gr-crete-local-rosters",
        "gr-dodecanese-local-rosters",
        "gr-mount-athos-twenty-ruling-monasteries",
        "gr-parallel-canonical-bodies",
        "gr-search-and-map-discoveries",
    }
    if candidate_ids != expected_ids:
        raise ValueError("Greece candidate ledger holdings drifted")
    return ledger


def build():
    result = []
    seen = set(EXISTING_PARENTS)
    owners = {parent: parent for parent in EXISTING_PARENTS}
    ids = set()
    signatures = {}
    rank_counts = Counter()
    kind_counts = Counter()
    parent_counts = Counter()
    for source in ROWS:
        row = clean(source)
        row_id = row.get("id")
        if not row_id or row_id in ids or row_id in EXISTING_PARENTS:
            raise ValueError("duplicate or missing id: %s" % row_id)
        parent = row.get("parent")
        if parent not in seen:
            raise ValueError("%s precedes or lacks its parent %s" %
                             (row_id, parent))
        owner = owners[parent]
        if row.get("country") != "GR":
            raise ValueError("%s carries the wrong country" % row_id)
        if row.get("kind") not in ALLOWED_KINDS:
            raise ValueError("%s carries an unsupported kind" % row_id)
        if row.get("rank") not in ALLOWED_RANKS:
            raise ValueError("%s carries an unsupported rank" % row_id)
        if not row.get("name") or not row.get("local"):
            raise ValueError(
                "%s lacks a usable English or Greek name" % row_id)
        if not any("\u0370" <= char <= "\u03ff"
                   for char in row["local"]):
            raise ValueError(
                "%s does not preserve its Greek source name" % row_id)
        if any(FORBIDDEN_PUNCTUATION.search(text)
               for text in walk_strings(row)):
            raise ValueError("%s contains forbidden punctuation" % row_id)
        for email in row.get("emails") or []:
            if not EMAIL_RE.match(email):
                raise ValueError("%s carries an invalid email" % row_id)
        for phone in row.get("phones") or []:
            digits = re.sub(r"\D", "", phone)
            if len(digits) < 7 or len(digits) > 15:
                raise ValueError("%s carries an invalid phone" % row_id)
        signature = (
            parent, row.get("rank"), unicase(row.get("local")))
        previous = signatures.get(signature)
        if previous and {previous, row_id} != ALLOWED_DUPLICATE_PAIR:
            raise ValueError(
                "%s duplicates %s after Greek identity normalization" %
                (row_id, previous))
        if not previous:
            signatures[signature] = row_id
        ids.add(row_id)
        seen.add(row_id)
        owners[row_id] = owner
        rank_counts[row["rank"]] += 1
        kind_counts[row["kind"]] += 1
        parent_counts[parent] += 1
        result.append(row)
    if len(result) != EXPECTED_COUNT:
        raise ValueError("expected %d bodies, found %d" %
                         (EXPECTED_COUNT, len(result)))
    if set(ENGLISH_NAMES) != ids:
        raise ValueError("Greece English name coverage drifted")
    if dict(sorted(rank_counts.items())) != EXPECTED_RANKS:
        raise ValueError("Greece rank counts drifted: %r" % rank_counts)
    if dict(sorted(kind_counts.items())) != EXPECTED_KINDS:
        raise ValueError("Greece kind counts drifted: %r" % kind_counts)
    if dict(sorted(parent_counts.items())) != EXPECTED_PARENT_COUNTS:
        raise ValueError("Greece parent counts drifted")
    contacts = sum(
        bool(row.get("phones") or row.get("emails") or row.get("site"))
        for row in result)
    phones = sum(bool(row.get("phones")) for row in result)
    emails = sum(bool(row.get("emails")) for row in result)
    sites = sum(bool(row.get("site")) for row in result)
    if (contacts, phones, emails, sites) != (
            EXPECTED_CONTACT_BODIES, EXPECTED_PHONE_BODIES,
            EXPECTED_EMAIL_BODIES, EXPECTED_SITE_BODIES):
        raise ValueError("Greece contact coverage drifted")
    validate_ledger()
    grouped = {}
    for row in result:
        grouped.setdefault(owners[row["id"]], []).append(row)
    if set(grouped) != EXISTING_PARENTS:
        raise ValueError("Greece branch ownership drifted")
    return {
        parent: {
            "v": 1, "parent": parent, "country": "GR",
            "rows": group_rows,
        }
        for parent, group_rows in grouped.items()
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--dump", action="store_true")
    args = parser.parse_args()
    payloads = build()
    if args.dump:
        print(json.dumps(payloads, ensure_ascii=False, indent=2))
    if args.check or not args.dump:
        print(
            "Greece: %d officially named bodies; "
            "21 regions, 146 parishes, 12 cemetery churches, "
            "29 monasteries or hesychasteria, and 155 rendered chapels; "
            "%d bodies carry current official contact data" %
            (EXPECTED_COUNT, EXPECTED_CONTACT_BODIES)
        )


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print("ERROR: %s" % exc, file=sys.stderr)
        raise SystemExit(1)
